import { readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const sourcePath = resolve(projectRoot, "assets/catjam.webm");
const outputPath = resolve(projectRoot, "src/catVideo.ts");

const video = await readFile(sourcePath);
const dataUrl = `data:video/webm;base64,${video.toString("base64")}`;
const moduleSource = [
  "// Generated by scripts/embed-asset.mjs. Do not edit manually.",
  `const catVideo = ${JSON.stringify(dataUrl)};`,
  "export default catVideo;",
  "",
].join("\n");

await writeFile(outputPath, moduleSource);
console.log(`Embedded assets/catjam.webm (${video.byteLength} bytes)`);
